// Build Alert: turns n8n's error details into a plain-English email and a Run Log row
const ADMIN = 'the automation admin'; // who to contact when the reader can't fix it themselves

// Must match the node names in the main workflow exactly
const WRITE_NODES = ['Clear Ranked', 'Clear Needs Review', 'Ranked Rows', 'Append Ranked', 'Review Rows', 'Append Needs Review'];
const LOG_NODES = ['Run Log Row', 'Append Run Log'];

const e = $input.first().json;
const now = $now.toFormat('dd/MM/yyyy HH:mm:ss');
const runId = `${$now.toFormat('yyyy-MM-dd HH:mm')} #${e.execution?.id ?? ''}`; // same format as successful runs
const message = e.execution?.error?.message ?? e.trigger?.error?.message ?? 'Unknown error';
const failedNode = e.execution?.lastNodeExecuted ?? 'unknown step';
const m = message.toLowerCase();

// Is the list in the Sheet still safe to use? Depends on WHERE it failed.
let safe;
if (WRITE_NODES.includes(failedNode)) {
  safe = `NO. The run stopped while writing the new list, so the Ranked and/or Needs Review tabs may be empty or only half-filled. ` +
    `Do not use them until this is fixed. To see the last good list, open the Sheet and go to File > Version history, ` +
    `and look at the version from before ${now}.`;
} else if (LOG_NODES.includes(failedNode)) {
  safe = 'Yes. The Ranked and Needs Review tabs WERE updated in this run. Only the Run Log entry could not be written.';
} else {
  safe = 'Yes. The Ranked and Needs Review tabs still show the list from the last successful run. ' +
    'They were NOT updated. Check the Run Log tab for when that was.';
}

// Plain-English "what to do", based on what failed
let whatToDo;
if (failedNode === 'Validate Rules') {
  whatToDo = 'Someone edited the Rules tab and a row has a mistake (the details below say which row). Open the Rules tab, fix that row (check spelling and dates). It will work on the next run. Use File > Version history if you are unsure what changed.';
} else if (m.includes('csv is missing columns') || m.includes('csv has no rows')) {
  whatToDo = 'The backlog export is empty or looks different from usual (a column is missing or was renamed). Re-export the backlog with the standard columns, or ask the person who changed the export.';
} else if (m.includes('ai calls failed') && m.includes('check the prompt or model')) {
  whatToDo = `The AI service is answering, but its answers keep failing our checks. This needs a fix to the setup. Please forward this email to ${ADMIN}.`;
} else if (m.includes('ai calls failed')) {
  whatToDo = `The AI service is not answering. It may be down, or the API balance may have run out. Check the balance at console.anthropic.com. If the balance is fine, the next scheduled run will try again. If it fails again, forward this email to ${ADMIN}.`;
} else if (failedNode === 'Counts Check') {
  whatToDo = `A safety check found jobs that would have been lost or doubled, so nothing was written. Please forward this email to ${ADMIN}.`;
} else if (/quota|rate limit|too many requests|\b429\b/.test(m)) {
  whatToDo = `Google or the AI service asked us to slow down (too many requests). This usually clears by itself, and the next scheduled run should work. If it keeps happening, forward this email to ${ADMIN}.`;
} else if (/\b(401|403)\b|unauthori[sz]ed|forbidden|invalid_grant|invalid (x-)?api[ -]?key|credentials? (are |is )?(invalid|expired)|token (has )?expired|reconnect/.test(m)) {
  whatToDo = `A login to Google or the AI service has expired. ${ADMIN} needs to reconnect it in n8n (it takes about a minute).`;
} else {
  whatToDo = `Something unexpected went wrong. Please forward this email to ${ADMIN}.`;
}

return [{ json: {
  subject: `❌ Backlog ranking did not update (${failedNode})`,
  body:
    `WHAT HAPPENED\nThe backlog ranking did not run successfully on ${now}.\n\n` +
    `IS THE LIST STILL SAFE TO USE?\n${safe}\n\n` +
    `WHAT TO DO\n${whatToDo}\n\n` +
    `DETAILS (for ${ADMIN})\nStep: ${failedNode}\nError: ${message}\nExecution: ${e.execution?.url ?? e.execution?.id ?? ''}`,
  runLog: {
    'Run ID': runId,
    'Started': '',
    'Finished': now,
    'Result': 'Failed',
    'Error': `${failedNode}: ${message}`,
  },
} }];
